// ── Enrich awards database with person data ──
(function enrichPersonData() {
  if (typeof AWARDS_BROWSE_DATABASE === "undefined") return;
  const PERSON_CATS = new Set(["Best Actor","Best Actress","Best Supporting Actor","Best Supporting Actress","Best Director","Best Actor (Drama)","Best Actor (Comedy/Musical)","Best Actress (Drama)","Best Actress (Comedy/Musical)"]);
  for (const [festival, cats] of Object.entries(AWARDS_BROWSE_DATABASE)) {
    for (const [category, years] of Object.entries(cats)) {
      if (!PERSON_CATS.has(category)) continue;
      for (const [year, data] of Object.entries(years)) {
        const enrich = (entry) => {
          if (!entry || !entry.title) return;
          const key = `${festival}|${category}|${year}|${entry.title.toLowerCase()}`;
          const match = PERSON_AWARD_LOOKUP[key];
          if (match) { entry.person_name = match.person_name; entry.person_id = match.person_id; }
        };
        if (data.winners) data.winners.forEach(enrich);
        else if (data.winner) enrich(data.winner);
        if (data.nominees) data.nominees.forEach(enrich);
      }
    }
  }
})();

window.AWARDS_BROWSE_DATABASE = AWARDS_BROWSE_DATABASE;
window.PERSON_AWARD_LOOKUP = PERSON_AWARD_LOOKUP;